package com.cholopay.bankcore.api;

import com.cholopay.bankcore.service.CholoKeyService;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.time.Instant;
import java.util.UUID;

@RestController
@RequestMapping("/v1")
public class CholoKeyController {
    private final CholoKeyService service; private final String participant; private final UUID participantUuid; private final UUID network; private final String bankToken;
    public CholoKeyController(CholoKeyService service,@Value("${cholopay.participant-id:}") String participant,@Value("${PARTICIPANT_UUID:}") String participantUuid,@Value("${NETWORK_ID:}") String network,@Value("${BANK_API_TOKEN:}") String bankToken){this.service=service;this.participant=participant;this.participantUuid=parse(participantUuid);this.network=parse(network);this.bankToken=bankToken;}
    private UUID parse(String value){try{return value==null||value.isBlank()?null:UUID.fromString(value);}catch(Exception e){return null;}}
    @PostMapping("/keys") public ResponseEntity<?> create(@RequestHeader(value="Authorization",required=false) String auth,@RequestHeader(value="Idempotency-Key",required=false) String idem,@RequestBody CreateRequest r){if(!configured())return problem(503,"configuration_missing","la configuración bancaria no está disponible"); if(auth==null||!auth.startsWith("Bearer ")||auth.length()<8)return problem(401,"unauthorized","la autorización del cliente no es válida"); if(r==null||r.accountId()==null||r.keyType()==null||r.keyValue()==null||idem==null||idem.isBlank())return problem(400,"invalid_request","la cuenta, clave e idempotencia son obligatorias"); try{return ResponseEntity.status(201).body(service.create(participant,participantUuid,network,token(auth),r.accountId(),r.keyType(),r.keyValue(),r.accountKind(),idem));}catch(SecurityException e){return problem(401,"unauthorized","la autorización del cliente no es válida");}catch(IllegalArgumentException e){return problem(400,"invalid_request",e.getMessage());}catch(Exception e){return problem(409,"key_unavailable","la clave no está disponible");}}
    @GetMapping("/keys/{keyId}") public ResponseEntity<?> get(@RequestHeader(value="Authorization",required=false) String auth,@PathVariable UUID keyId){try{return ResponseEntity.ok(service.get(participant,participantUuid,token(auth),keyId));}catch(SecurityException e){return problem(404,"key_not_found","la clave no está disponible");}catch(com.cholopay.bankcore.service.CholoKeyDirectoryClient.DirectoryException e){return problem(e.status==404?404:503,e.status==404?"key_not_found":"directory_unavailable",e.status==404?"la clave no está disponible":"el directorio no está disponible");}catch(Exception e){return problem(503,"directory_unavailable","el directorio no está disponible");}}
    @PostMapping("/keys/{keyId}/{action:suspend|block|delete}") public ResponseEntity<?> transition(@RequestHeader(value="Authorization",required=false) String auth,@RequestHeader(value="Idempotency-Key",required=false) String idem,@PathVariable UUID keyId,@PathVariable String action){if(idem==null||idem.isBlank())return problem(400,"idempotency_key_required","se requiere la clave de idempotencia");try{service.transition(participant,participantUuid,token(auth),keyId,action,idem);return ResponseEntity.accepted().build();}catch(SecurityException e){return problem(404,"key_not_found","la clave no está disponible");}catch(Exception e){return problem(409,"key_transition_invalid","la transición de la clave no está disponible");}}
    @GetMapping("/keys/{keyId}/qr") public ResponseEntity<?> staticQr(@RequestHeader(value="Authorization",required=false) String auth,@PathVariable UUID keyId){try{return ResponseEntity.ok(new QrResponse(service.staticQr(participant,participantUuid,token(auth),keyId),"synthetic"));}catch(SecurityException e){return problem(404,"key_not_found","la clave no está disponible");}catch(Exception e){return problem(409,"qr_unavailable","el QR no está disponible");}}
    @PostMapping("/keys/{keyId}/qr/dynamic") public ResponseEntity<?> dynamicQr(@RequestHeader(value="Authorization",required=false) String auth,@PathVariable UUID keyId,@RequestBody DynamicRequest r){try{return ResponseEntity.status(201).body(new QrResponse(service.dynamicQr(participant,participantUuid,token(auth),keyId,r.amountMinor(),r.reference(),r.expiresAt()),"synthetic"));}catch(SecurityException e){return problem(404,"key_not_found","la clave no está disponible");}catch(Exception e){return problem(400,"invalid_qr","el QR dinámico no es válido");}}
    @PostMapping("/qr/verify") public ResponseEntity<?> verify(@RequestBody VerifyRequest r){var result=service.verifyQr(r==null?null:r.payload());return result.accepted()?ResponseEntity.ok(result):problem(409,result.reason(),result.reason().equals("payload_expirado")?"el QR dinámico expiró":"el QR dinámico ya fue utilizado");}
    private boolean configured(){return participant!=null&&!participant.isBlank()&&participantUuid!=null&&network!=null&&bankToken!=null&&!bankToken.isBlank();}
    private String token(String auth){if(auth==null||!auth.startsWith("Bearer ")||auth.length()<8)throw new SecurityException();return auth.substring(7);}
    private ResponseEntity<Problem> problem(int status,String code,String detail){return ResponseEntity.status(status).contentType(MediaType.valueOf("application/problem+json")).body(new Problem("https://api.cholopay.dev/problems/"+code,"Solicitud no válida",status,detail,code));}
    public record CreateRequest(UUID accountId,String keyType,String keyValue,String accountKind){} public record DynamicRequest(long amountMinor,String reference,Instant expiresAt){} public record VerifyRequest(String payload){} public record QrResponse(String payload,String environment){} public record Problem(String type,String title,int status,String detail,String code){}
}
